88: 		Recovery   string `json:"recovery_id"`
89: 	}{repository, recoveryID})
90: 	if err != nil {
91: 		return false, err
92: 	}
93: 	result, err := db.ExecContext(ctx, `INSERT INTO notices(project_id, task_id, kind, summary, data_json, created_at)
94: 		SELECT ?, ?, 'greenhouse_recovery_required', ?, ?, ?
95: 		WHERE NOT EXISTS (SELECT 1 FROM notices WHERE task_id=? AND kind='greenhouse_recovery_required' AND data_json=?)`,
96: 		projectID, taskID, summary, string(data), time.Now().UnixMilli(), taskID, string(data))
97: 	if err != nil {
98: 		return false, err
99: 	}
100: 	rows, err := result.RowsAffected()
101: 	if err != nil || rows == 0 {
102: 		return false, err
103: 	}
104: 	return true, db.PersistProject(ctx, projectID)
105: }
