267: func builtinReviewLatency(ctx context.Context, db *store.DB, projectID int64) (*int64, error) {
268: 	rows, err := db.QueryContext(ctx, `SELECT rr.created_at, (SELECT MIN(s.at) FROM signals s WHERE s.task_id=rr.review_task_id AND s.verb='done') FROM review_rounds rr JOIN tasks t ON t.id=rr.ship_task_id WHERE (?=0 OR t.project_id=?) AND rr.status='verdict'`, projectID, projectID)
269: 	if err != nil {
270: 		return nil, err
271: 	}
272: 	defer rows.Close()
273: 	var values []int64
274: 	for rows.Next() {
275: 		var started int64
276: 		var settled sql.NullInt64
277: 		if err := rows.Scan(&started, &settled); err != nil {
278: 			return nil, err
279: 		}
280: 		if settled.Valid && settled.Int64 >= started {
281: 			values = append(values, settled.Int64-started)
282: 		}
283: 	}
284: 	if err := rows.Err(); err != nil {
285: 		return nil, err
286: 	}
287: 	if len(values) == 0 {
288: 		return nil, nil
289: 	}
290: 	median := medianInt64(values)
291: 	return &median, nil
292: }
