294: func builtinFixedFindings(ctx context.Context, db *store.DB, projectID int64) ([]builtinFixedFinding, error) {
295: 	rows, err := db.QueryContext(ctx, `SELECT f.ship_task_id,f.head_sha,f.repository,f.path,p.root_cause FROM review_findings f JOIN review_patterns p ON p.id=f.pattern_id JOIN tasks t ON t.id=f.ship_task_id WHERE t.project_id=? AND f.origin='introduced' AND f.in_scope=1 AND f.state='fixed' AND f.severity IN ('P0','P1')`, projectID)
296: 	if err != nil {
297: 		return nil, err
298: 	}
299: 	defer rows.Close()
300: 	var findings []builtinFixedFinding
301: 	for rows.Next() {
302: 		var finding builtinFixedFinding
303: 		if err := rows.Scan(&finding.TaskID, &finding.Head, &finding.Repo, &finding.Path, &finding.Cause); err != nil {
304: 			return nil, err
305: 		}
306: 		findings = append(findings, finding)
307: 	}
308: 	return findings, rows.Err()
309: }
