871: func recordAutoStartReviewerReadiness(ctx context.Context, db *store.DB, project store.Project, change store.Task, targets []store.ReviewTarget, failure *axi.Error) error {
872: 	heads := make([]string, len(targets))
873: 	for i, target := range targets {
874: 		heads[i] = target.Repository + "@" + shortSHA(target.Commit)
875: 	}
876: 	head := strings.Join(heads, ", ")
877: 	var found bool
878: 	if err := db.QueryRowContext(ctx, `SELECT EXISTS(SELECT 1 FROM notices WHERE project_id=? AND task_id=? AND kind='review_auto_start_skipped' AND json_valid(data_json) AND json_extract(data_json,'$.head')=?)`, project.ID, change.ID, head).Scan(&found); err != nil || found {
879: 		return err
880: 	}
881: 	summary := fmt.Sprintf("%s: Review auto-start skipped at %s because no eligible reviewer is available: %s. Configure a reviewer Profile, then run `posse review start %s --profile <profile>`.", change.Title, head, failure.Message, taskIDString(change.Seq))
882: 	data := marshalJSON(map[string]any{"head": head, "reason_code": failure.Code, "reason": failure.Message, "help": failure.Help})
883: 	_, err := db.CreateNotice(ctx, store.Notice{ProjectID: project.ID, TaskID: change.ID, Kind: "review_auto_start_skipped", Summary: summary, DataJSON: data})
884: 	return err
885: }
