960: func (s *Service) maybeAutoStartReviewRound(ctx *axi.Context, db *store.DB, home string, project store.Project, change store.Task) (bool, error) {
961: 	plan, err := change.AdmittedPlan()
962: 	if err != nil {
963: 		return false, admittedPlanFailure(err)
964: 	}
965: 	parallel := plan != nil && plan.ValidationLoops != nil && plan.ValidationLoops.ReviewParallel == "greenhouse"
966: 	if !parallel && !autoStartReviewLoop(plan) {
967: 		return false, nil
968: 	}
969: 	targets, err := changeCandidateTargets(ctx.Context, db, project, change)
970: 	if err != nil {
971: 		return false, err
972: 	}
973: 	if project.IsWorkspace() {
974: 		taskRepos, err := db.TaskRepos(ctx.Context, change.ID)
975: 		if err != nil {
976: 			return false, err
977: 		}
978: 		gated := make(map[string]string, len(taskRepos))
979: 		for _, repo := range taskRepos {
980: 			gated[repo.Repo] = repo.GatedSHA
981: 		}
982: 		for _, target := range targets {
983: 			if gated[target.Repository] == "" || gated[target.Repository] != target.Commit {
984: 				return false, nil
985: 			}
986: 		}
987: 	} else if len(targets) != 1 || change.GatedSHA == "" || targets[0].Commit != change.GatedSHA {
988: 		return false, nil
989: 	}
990: 	if !autoStartReviewLoop(plan) {
991: 		if parallel {
992: 			if err := s.startParallelGreenhouseReviews(ctx.Context, db, home, project, change, targets); err != nil {
993: 				return false, err
994: 			}
995: 		}
996: 		return false, nil
997: 	}
998: 	if covered, err := db.ReviewTargetsCovered(ctx.Context, change.ID, targets); err != nil || covered {
999: 		return false, err
1000: 	}
1001: 	profile, err := s.autoStartReviewProfile(ctx.Context, project, home)
1002: 	if err == nil {
1003: 		err = s.startReviewRound(ctx, db, home, project, change, profile, "")
1004: 	}
1005: 	if failure, unavailable := autoStartReviewerUnavailable(err); unavailable {
1006: 		if noticeErr := recordAutoStartReviewerReadiness(ctx.Context, db, project, change, targets, failure); noticeErr != nil {
1007: 			return false, noticeErr
1008: 		}
1009: 		return false, nil
1010: 	}
1011: 	var failure *axi.Error
1012: 	if errors.As(err, &failure) && (failure.Code == "review_round_unchanged" || failure.Code == "review_round_active") {
1013: 		return false, nil
1014: 	}
1015: 	return err == nil, err
1016: }
