887: func (s *Service) startParallelGreenhouseReviews(ctx context.Context, db *store.DB, home string, project store.Project, change store.Task, targets []store.ReviewTarget) error {
888: 	requests, err := db.GreenhouseReviewRequests(ctx, project.ID)
889: 	if err != nil {
890: 		return err
891: 	}
892: 	for _, target := range targets {
893: 		exists := false
894: 		for _, request := range requests {
895: 			if request.TaskID == change.ID && request.Repository == target.Repository && request.RequestedHead == target.Commit && request.Outcome == "verdict" {
896: 				exists = true
897: 				break
898: 			}
899: 		}
900: 		pending := filepath.Join(home, "projects", project.Name, "tasks", taskIDString(change.Seq), "greenhouse", target.Repository+".pending.json")
901: 		if _, err := os.Stat(pending); err == nil {
902: 			exists = true
903: 		} else if !errors.Is(err, os.ErrNotExist) {
904: 			return err
905: 		}
906: 		if exists {
907: 			continue
908: 		}
909: 		requestStarted := time.Now().UnixMilli()
910: 		recordFailure := func(reason string) error {
911: 			if err := db.RecordGreenhouseReviewRequest(ctx, store.GreenhouseReviewRequest{ProjectID: project.ID, TaskID: change.ID, Repository: target.Repository, RequestedHead: target.Commit, Provider: store.GreenhouseReviewProvider, RequestedAt: requestStarted, SettledAt: time.Now().UnixMilli(), Outcome: "failed"}); err != nil {
912: 				return err
913: 			}
914: 			_, err := db.CreateGreenhouseFailureNoticeOnce(ctx, project.ID, change.ID, target.Repository, target.Commit, reason)
915: 			return err
916: 		}
917: 		binary, err := os.Executable()
918: 		if err != nil {
919: 			if recordErr := recordFailure(err.Error()); recordErr != nil {
920: 				return recordErr
921: 			}
922: 			continue
923: 		}
924: 		args := []string{"_greenhouse", "review", taskIDString(change.Seq)}
925: 		if project.IsWorkspace() {
926: 			args = append(args, "--repo", target.Repository)
927: 		}
928: 		command := exec.Command(binary, args...)
929: 		command.Dir = project.Root
930: 		command.Env = os.Environ()
931: 		command.SysProcAttr = &syscall.SysProcAttr{Setsid: true}
932: 		logDir := filepath.Join(home, "projects", project.Name, "tasks", taskIDString(change.Seq), "greenhouse")
933: 		if err := os.MkdirAll(logDir, 0o700); err != nil {
934: 			if recordErr := recordFailure(err.Error()); recordErr != nil {
935: 				return recordErr
936: 			}
937: 			continue
938: 		}
939: 		log, err := os.OpenFile(filepath.Join(logDir, target.Repository+".parallel.log"), os.O_CREATE|os.O_APPEND|os.O_WRONLY, 0o600)
940: 		if err != nil {
941: 			if recordErr := recordFailure(err.Error()); recordErr != nil {
942: 				return recordErr
943: 			}
944: 			continue
945: 		}
946: 		command.Stdout, command.Stderr = log, log
947: 		if err := command.Start(); err != nil {
948: 			log.Close()
949: 			if recordErr := recordFailure(err.Error()); recordErr != nil {
950: 				return recordErr
951: 			}
952: 			continue
953: 		}
954: 		_ = log.Close()
955: 		go func() { _ = command.Wait() }()
956: 	}
957: 	return nil
958: }
